/* From the studio archive: the prints' hover films and the section's motion. */
(function () {
  var root = document.querySelector('.arch');
  if (!root) return;
  var items = [].slice.call(root.querySelectorAll('.arch__item'));
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  var hint = root.querySelector('.arch__hint');
  if (hint) hint.textContent = fine ? 'Hover a print to watch the craft' : 'Tap a print to watch the craft';

  // a print turns into its film: loaded on first use, paused when let go
  function off(it) {
    it.classList.remove('is-on');
    var v = it.querySelector('video');
    if (v) v.pause();
  }
  function on(it) {
    items.forEach(function (o) { if (o !== it) off(o); });
    it.classList.add('is-on');
    var v = it.querySelector('video');
    if (!v) return;
    if (!v.getAttribute('src')) v.setAttribute('src', it.getAttribute('data-film'));
    var p = v.play();
    if (p && p.catch) p.catch(function () {});
  }
  items.forEach(function (it) {
    if (fine) {
      it.addEventListener('pointerenter', function () { on(it); });
      it.addEventListener('pointerleave', function () { off(it); });
    } else {
      it.addEventListener('click', function () { if (it.classList.contains('is-on')) off(it); else on(it); });
    }
    // keyboard focus opens a print too; a tap's focus does not, or the tap
    // would open it and its click close it again
    it.addEventListener('focus', function () { if (it.matches(':focus-visible')) on(it); });
    it.addEventListener('blur', function () { off(it); });
  });

  // the title's words, each in a clipping box
  root.querySelectorAll('.arch__line').forEach(function (line) {
    line.innerHTML = line.textContent.trim().split(/\s+/).map(function (w) {
      return '<span class="arch__w"><span class="arch__wi">' + w + '</span></span>';
    }).join(' ');
  });

  function motion() {
    var gsap = window.gsap;
    if (!gsap || !window.ScrollTrigger || reduced) return;
    var strips = root.querySelector('.arch__strips');

    gsap.fromTo(root.querySelector('.arch__meta'), { opacity: 0, y: 14 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.arch__meta'), start: 'top 90%' },
    });
    gsap.fromTo(root.querySelectorAll('.arch__wi'), { yPercent: 112 }, {
      yPercent: 0, duration: 1.35, stagger: 0.07, ease: 'expo.out',
      scrollTrigger: { trigger: root.querySelector('.arch__title'), start: 'top 84%' },
    });

    // the prints rise in one after another
    gsap.fromTo(root.querySelectorAll('.arch__strip'), { clipPath: 'inset(100% 0% 0% 0%)' }, {
      clipPath: 'inset(0% 0% 0% 0%)', duration: 1.3, stagger: 0.09, ease: 'expo.out',
      scrollTrigger: { trigger: strips, start: 'top 82%' },
    });
    gsap.fromTo(root.querySelectorAll('.arch__label, .arch__names li, .arch__caption'), { opacity: 0, y: 12 }, {
      opacity: 1, y: 0, duration: 0.9, stagger: 0.06, ease: 'power3.out',
      scrollTrigger: { trigger: strips, start: 'top 70%' },
    });
    // and take their colour as the section passes, as the old poster did
    gsap.fromTo(root.querySelectorAll('.arch__paint'), { filter: 'grayscale(1)' }, {
      filter: 'grayscale(0)', ease: 'none',
      scrollTrigger: { trigger: strips, start: 'top 78%', end: 'center 45%', scrub: 0.6 },
    });
    // each print hangs at its own depth
    var drift = [10, -38, -6, -52, -18, -30];
    items.forEach(function (it, i) {
      gsap.fromTo(it, { y: -drift[i] * 0.6 }, {
        y: drift[i], ease: 'none',
        scrollTrigger: { trigger: strips, start: 'top bottom', end: 'bottom top', scrub: 0.8 },
      });
    });
    gsap.fromTo(root.querySelector('.arch__foot'), { opacity: 0, y: 20 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.arch__foot'), start: 'top 90%' },
    });
  }

  if (window.__sjRevealed || !document.querySelector('.sj-loader')) motion();
  else document.addEventListener('sj:revealed', motion, { once: true });
})();

/* What Shrujan has mastered: the grid's motion and the "View" disc. */
(function () {
  var root = document.querySelector('.idx');
  if (!root) return;
  var grid = root.querySelector('.col__grid');
  var tiles = [].slice.call(root.querySelectorAll('.col__tile'));
  var cursor = root.querySelector('.col__cursor');
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var gsap = window.gsap;

  // ---------- the "View" disc, following the cursor over the tiles ----------
  if (fine && cursor && grid) {
    grid.classList.add('has-cursor');
    var x = 0, y = 0, tx = 0, ty = 0, raf = 0, on = false;
    var tick = function () {
      x += (tx - x) * 0.2;
      y += (ty - y) * 0.2;
      cursor.style.transform = 'translate3d(' + (x - 46) + 'px,' + (y - 46) + 'px,0)';
      if (on || Math.abs(tx - x) > 0.5 || Math.abs(ty - y) > 0.5) raf = requestAnimationFrame(tick);
      else raf = 0;
    };
    var run = function () { if (!raf) raf = requestAnimationFrame(tick); };
    tiles.forEach(function (t) {
      var media = t.querySelector('.col__media');
      media.addEventListener('pointerenter', function (e) {
        if (!on) { x = tx = e.clientX; y = ty = e.clientY; }
        on = true;
        cursor.classList.add('is-on');
        run();
      });
      media.addEventListener('pointermove', function (e) { tx = e.clientX; ty = e.clientY; run(); });
      media.addEventListener('pointerleave', function () { on = false; cursor.classList.remove('is-on'); });
    });
  }

  // ---------- the title's words ----------
  root.querySelectorAll('.idx__line').forEach(function (line) {
    line.innerHTML = line.textContent.trim().split(/\s+/).map(function (w) {
      return '<span class="idx__w"><span class="idx__wi">' + w + '</span></span>';
    }).join(' ');
  });

  // ---------- motion ----------
  function motion() {
    if (!gsap || !window.ScrollTrigger || reduced) return;
    gsap.fromTo(root.querySelector('.idx__meta'), { opacity: 0, y: 14 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.idx__meta'), start: 'top 90%' },
    });
    gsap.fromTo(root.querySelectorAll('.idx__wi'), { yPercent: 112 }, {
      yPercent: 0, duration: 1.35, stagger: 0.07, ease: 'expo.out',
      scrollTrigger: { trigger: root.querySelector('.idx__title'), start: 'top 85%' },
    });
    gsap.fromTo(root.querySelector('.idx__lede'), { opacity: 0, y: 18 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.idx__head'), start: 'top 75%' },
    });
    // each tile's frame opens from the bottom, its photograph settling as it
    // does, then its caption; tiles further down the grid follow on
    tiles.forEach(function (t, i) {
      var tl = gsap.timeline({ scrollTrigger: { trigger: t, start: 'top 90%' } });
      tl.fromTo(t.querySelector('.col__media'), { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.25, ease: 'expo.out', delay: (i % 3) * 0.08 })
        .fromTo(t.querySelector('.col__img'), { scale: 1.22 }, { scale: 1, duration: 1.6, ease: 'expo.out' }, '<')
        .fromTo(t.querySelector('.col__cap'), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.8, ease: 'power3.out' }, '<0.35');
      // and the photograph drifts inside its frame as the page moves
      gsap.fromTo(t.querySelector('.col__img'), { yPercent: -5 }, {
        yPercent: 5, ease: 'none',
        scrollTrigger: { trigger: t, start: 'top bottom', end: 'bottom top', scrub: 0.8 },
      });
    });
    gsap.fromTo(root.querySelector('.idx__foot'), { opacity: 0, y: 16 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.idx__foot'), start: 'top 95%' },
    });
  }

  if (window.__sjRevealed || !document.querySelector('.sj-loader')) motion();
  else document.addEventListener('sj:revealed', motion, { once: true });
})();

/* Craft that cares: the arches closing in, the seals drawing themselves,
   the words turning round them, and the section's entrance. */
(function () {
  var root = document.querySelector('.prm');
  if (!root) return;
  var seals = [].slice.call(root.querySelectorAll('.prm__seal'));
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var gsap = window.gsap;

  // the title's words
  root.querySelectorAll('.prm__line').forEach(function (line) {
    line.innerHTML = line.textContent.trim().split(/\s+/).map(function (w) {
      return '<span class="prm__w"><span class="prm__wi">' + w + '</span></span>';
    }).join(' ');
  });

  // the ring of words: as many of the seal's words as fit once round its
  // circle at their natural spacing, then spread to close the circle
  var ORBIT = 536;
  function fillOrbits() {
    var ctx = document.createElement('canvas').getContext('2d');
    root.querySelectorAll('.prm__spin').forEach(function (svg) {
      var text = svg.querySelector('text');
      var path = svg.querySelector('textPath');
      var cs = getComputedStyle(text);
      var size = parseFloat(cs.fontSize) || 9.2;
      var track = (parseFloat(cs.letterSpacing) || size * 0.2);
      ctx.font = cs.fontWeight + ' ' + size + 'px ' + cs.fontFamily;
      var width = function (str) { return ctx.measureText(str.toUpperCase()).width + track * str.length; };
      var name = svg.getAttribute('data-name');
      var plan = [name, 'Shrujan', name, 'Kutch', name, 'Shrujan', name, 'Kutch'];
      var fill = ['Kutch', '1969'];
      var out = '';
      for (var k = 0; k < plan.length; k++) {
        if (width(out + plan[k] + ' · ') > ORBIT * 1.03) break;
        out += plan[k] + ' · ';
      }
      fill.forEach(function (f) { if (width(out + f + ' · ') <= ORBIT * 1.03) out += f + ' · '; });
      path.textContent = out;
      text.setAttribute('textLength', ORBIT);
    });
  }
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fillOrbits);
  else fillOrbits();

  function motion() {
    if (!gsap || !window.ScrollTrigger || reduced) return;
    var desktop = window.matchMedia('(min-width: 721px)').matches;
    var stage = root.querySelector('.prm__stage');
    var row = root.querySelector('.prm__seals');

    gsap.fromTo(root.querySelector('.prm__meta'), { opacity: 0, y: 14 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.prm__meta'), start: 'top 90%' },
    });
    gsap.fromTo(root.querySelectorAll('.prm__wi'), { yPercent: 112 }, {
      yPercent: 0, duration: 1.35, stagger: 0.06, ease: 'expo.out',
      scrollTrigger: { trigger: root.querySelector('.prm__title'), start: 'top 85%' },
    });
    gsap.fromTo(root.querySelector('.prm__lede'), { opacity: 0, y: 16 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.prm__lede'), start: 'top 90%' },
    });

    // the arches slide in from the screen edges once as the seals arrive,
    // then stay where they are; the scroll never moves them
    root.querySelectorAll('.prm__arch').forEach(function (a) {
      var dir = a.classList.contains('prm__arch--left') ? -1 : 1;
      gsap.fromTo(a, { xPercent: 100 * dir, opacity: 0 }, {
        xPercent: 0, opacity: 1, duration: 1.9, ease: 'expo.out',
        scrollTrigger: { trigger: stage, start: 'top 85%' },
      });
    });

    // each seal: its ring draws round, the photograph opens from the
    // centre, the words come round it, then the name and the line
    var tl = gsap.timeline({ scrollTrigger: { trigger: row, start: desktop ? 'top 78%' : 'top 88%' } });
    seals.forEach(function (s, i) {
      var at = i * 0.14;
      tl.fromTo(s.querySelector('.prm__draw circle'), { strokeDashoffset: 1 }, { strokeDashoffset: 0, duration: 1.7, ease: 'power2.inOut' }, at)
        .fromTo(s.querySelector('.prm__photo'), { clipPath: 'circle(0% at 50% 50%)' }, { clipPath: 'circle(50% at 50% 50%)', duration: 1.4, ease: 'expo.out' }, at + 0.25)
        .fromTo(s.querySelector('.prm__photo img'), { scale: 1.4 }, { scale: 1, duration: 1.8, ease: 'expo.out' }, at + 0.25)
        .fromTo(s.querySelector('.prm__spin'), { opacity: 0, rotate: -50 }, { opacity: 1, rotate: 0, duration: 1.8, ease: 'expo.out' }, at + 0.45)
        .fromTo(s.querySelectorAll('.prm__no, .prm__name, .prm__copy'), { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 1, stagger: 0.07, ease: 'power3.out' }, at + 0.4);
      // the hover turn is a CSS transition; let it run once the entrance is done
      tl.add(function () { s.querySelector('.prm__spin').style.removeProperty('rotate'); gsap.set(s.querySelector('.prm__spin'), { clearProps: 'rotate' }); }, at + 2.3);
    });

    // the words keep turning as the page moves, alternate seals the other way
    seals.forEach(function (s, i) {
      gsap.fromTo(s.querySelector('.prm__orbit'), { rotation: 0 }, {
        rotation: i % 2 ? -110 : 110, ease: 'none',
        scrollTrigger: { trigger: row, start: 'top bottom', end: 'bottom top', scrub: 0.8 },
      });
    });

    gsap.fromTo(root.querySelector('.prm__more'), { opacity: 0, y: 16 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.prm__more'), start: 'top 95%' },
    });
  }

  if (window.__sjRevealed || !document.querySelector('.sj-loader')) motion();
  else document.addEventListener('sj:revealed', motion, { once: true });
})();

/* Shrujan in motion: the films opening, the tags swinging, the "Watch"
   disc, and the seal turning with the scroll. */
(function () {
  var root = document.querySelector('.reels');
  if (!root) return;
  var rail = root.querySelector('.reels__rail');
  var cursor = root.querySelector('.rl__cursor');
  var link = root.querySelector('.reels__seal-link');
  var badge = root.querySelector('.reels__seal-badge');
  var ring = root.querySelector('.reels__seal svg');
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var gsap = window.gsap;
  if (!rail) return;
  // on a phone the theme has already copied the cards for its looping rail,
  // so this takes in the copies as well
  var cards = [].slice.call(rail.querySelectorAll('.reel'));

  // ---------- the title's words ----------
  root.querySelectorAll('.rl__line').forEach(function (line) {
    line.innerHTML = line.textContent.trim().split(/\s+/).map(function (w) {
      return '<span class="rl__w"><span class="rl__wi">' + w + '</span></span>';
    }).join(' ');
  });

  // ---------- the "Watch" disc ----------
  if (fine && cursor) {
    rail.classList.add('has-cursor');
    var x = 0, y = 0, tx = 0, ty = 0, craf = 0, on = false;
    var follow = function () {
      x += (tx - x) * 0.2;
      y += (ty - y) * 0.2;
      cursor.style.transform = 'translate3d(' + (x - 46) + 'px,' + (y - 46) + 'px,0)';
      if (on || Math.abs(tx - x) > 0.5 || Math.abs(ty - y) > 0.5) craf = requestAnimationFrame(follow);
      else craf = 0;
    };
    var run = function () { if (!craf) craf = requestAnimationFrame(follow); };
    cards.forEach(function (c) {
      var media = c.querySelector('.reel__media');
      media.addEventListener('pointerenter', function (e) {
        if (!on) { x = tx = e.clientX; y = ty = e.clientY; }
        on = true;
        cursor.classList.add('is-on');
        run();
      });
      media.addEventListener('pointermove', function (e) { tx = e.clientX; ty = e.clientY; run(); });
      media.addEventListener('pointerleave', function () { on = false; cursor.classList.remove('is-on'); });
    });
  }

  if (!gsap || reduced) return;

  // ---------- a reel's tag swings when the cursor comes onto it ----------
  if (fine) {
    cards.forEach(function (c) {
      var tag = c.querySelector('.reel__letter');
      if (!tag) return;
      c.addEventListener('pointerenter', function (e) {
        var r = c.getBoundingClientRect();
        var from = e.clientX < r.left + r.width / 2 ? 9 : -9;
        // only the swing is replaced: a cursor resting on a card as the row
        // arrives must not cut its tag's drop-in short and leave it hidden
        gsap.fromTo(tag, { rotation: from }, { rotation: 0, duration: 1.8, ease: 'elastic.out(1, 0.28)', transformOrigin: '50% 0%', overwrite: 'auto' });
      });
    });
  }

  // ---------- the seal: turns on its own, quicker with the scroll, backwards
  // when the page goes back up; its badge leans after the cursor ----------
  var spin = ring ? gsap.to(ring, { rotation: 360, duration: 26, ease: 'none', repeat: -1, transformOrigin: '50% 50%' }) : null;
  var dir = 1, hover = false;
  function settle() { return gsap.to(spin, { timeScale: dir * (hover ? 4 : 1), duration: 1.2, ease: 'power2.out' }); }
  if (spin && window.ScrollTrigger) {
    window.ScrollTrigger.create({
      trigger: root, start: 'top bottom', end: 'bottom top',
      onUpdate: function (st) {
        dir = st.direction < 0 ? -1 : 1;
        var boost = Math.min(7, Math.abs(st.getVelocity()) / 260);
        gsap.to(spin, { timeScale: dir * (1 + boost), duration: 0.25, overwrite: true, onComplete: settle });
      },
    });
  }
  if (link && fine) {
    link.addEventListener('pointerenter', function () { hover = true; if (spin) gsap.to(spin, { timeScale: dir * 4, duration: 0.6, overwrite: true }); });
    link.addEventListener('pointermove', function (e) {
      var r = link.getBoundingClientRect();
      gsap.to(badge, { x: (e.clientX - r.left - r.width / 2) * 0.35, y: (e.clientY - r.top - r.height / 2) * 0.35, duration: 0.5, ease: 'power3.out' });
    });
    link.addEventListener('pointerleave', function () {
      hover = false;
      if (spin) settle();
      gsap.to(badge, { x: 0, y: 0, duration: 1.2, ease: 'elastic.out(1, 0.35)' });
    });
  }

  // ---------- the entrance ----------
  function motion() {
    if (!window.ScrollTrigger) return;
    var desktop = window.matchMedia('(min-width: 721px)').matches;
    gsap.fromTo(root.querySelector('.reels__meta'), { opacity: 0, y: 14 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.reels__meta'), start: 'top 90%' },
    });
    gsap.fromTo(root.querySelectorAll('.rl__wi'), { yPercent: 112 }, {
      yPercent: 0, duration: 1.35, stagger: 0.07, ease: 'expo.out',
      scrollTrigger: { trigger: root.querySelector('.rl__title'), start: 'top 85%' },
    });
    gsap.fromTo(root.querySelector('.reels__note'), { opacity: 0, y: 16 }, {
      opacity: 1, y: 0, duration: 1, ease: 'power3.out',
      scrollTrigger: { trigger: root.querySelector('.reels__head'), start: 'top 80%' },
    });
    if (link) {
      gsap.fromTo(link, { scale: 0.4, opacity: 0, rotation: -120 }, {
        scale: 1, opacity: 1, rotation: 0, duration: 1.6, ease: 'expo.out',
        scrollTrigger: { trigger: root.querySelector('.reels__head'), start: 'top 80%' },
      });
    }

    // the films open from the foot one after another, the picture settling
    // as it does, then the words on them; then each tag drops open from the
    // card's edge and swings to rest
    var shown = desktop ? cards : cards.filter(function (c) {
      var r = c.getBoundingClientRect();
      return r.right > 0 && r.left < window.innerWidth;
    });
    var tl = gsap.timeline({ scrollTrigger: { trigger: rail, start: desktop ? 'top 82%' : 'top 88%' } });
    shown.forEach(function (c, i) {
      var at = i * 0.1;
      var tag = c.querySelector('.reel__letter');
      tl.fromTo(c.querySelector('.reel__media'), { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.3, ease: 'expo.out', clearProps: 'clipPath' }, at)
        .fromTo(c.querySelector('video'), { scale: 1.28 }, { scale: 1, duration: 1.8, ease: 'expo.out', clearProps: 'scale,transform' }, at)
        .fromTo(c.querySelectorAll('.reel__no, .reel__title'), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.9, stagger: 0.05, ease: 'power3.out', clearProps: 'transform' }, at + 0.45);
      if (tag) {
        tl.fromTo(tag, { opacity: 0, scaleY: 0.15 }, { opacity: 1, scaleY: 1, duration: 0.7, ease: 'power3.out', transformOrigin: '50% 0%' }, at + 0.55)
          .fromTo(tag, { rotation: i % 2 ? 16 : -16 }, { rotation: 0, duration: 2.2, ease: 'elastic.out(1, 0.3)', transformOrigin: '50% 0%' }, at + 0.55);
      }
    });
  }

  if (window.__sjRevealed || !document.querySelector('.sj-loader')) motion();
  else document.addEventListener('sj:revealed', motion, { once: true });
})();

/* The rest of the home page: the heads' words rising, photographs opening
   from the foot as they come into view, words rising after them, and the
   craft's numbers counting up. Each plays once, as its block arrives. */
(function () {
  var gsap = window.gsap;
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var $ = function (s, r) { return [].slice.call((r || document).querySelectorAll(s)); };

  // the heads' words
  $('.hx__line').forEach(function (line) {
    line.innerHTML = line.textContent.trim().split(/\s+/).map(function (w) {
      return '<span class="hx__w"><span class="hx__wi">' + w + '</span></span>';
    }).join(' ');
  });

  function shown(el) { return !el.hidden && el.offsetParent !== null; }

  // a photograph opens from its foot, the picture settling inside it
  function open(frame, delay) {
    var img = frame.querySelector('img');
    var tl = gsap.timeline({ delay: delay || 0 });
    tl.fromTo(frame, { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.25, ease: 'expo.out', clearProps: 'clipPath' });
    if (img) tl.fromTo(img, { scale: 1.22 }, { scale: 1, duration: 1.7, ease: 'expo.out', clearProps: 'transform,scale' }, 0);
    return tl;
  }

  // frames in a row open one after another as the row comes into view
  function frames(sel, pick) {
    var els = $(sel).filter(shown);
    if (!els.length) return;
    els.forEach(function (el) { gsap.set(pick ? el.querySelector(pick) : el, { clipPath: 'inset(100% 0% 0% 0%)' }); });
    window.ScrollTrigger.batch(els, {
      start: 'top 90%', once: true,
      onEnter: function (batch) {
        batch.forEach(function (el, i) { open(pick ? el.querySelector(pick) : el, i * 0.09); });
      },
    });
  }

  // words and small blocks rise in, a little apart
  function rise(sel, start) {
    var els = $(sel).filter(shown);
    if (!els.length) return;
    gsap.set(els, { opacity: 0, y: 18 });
    window.ScrollTrigger.batch(els, {
      start: start || 'top 92%', once: true,
      onEnter: function (batch) { gsap.to(batch, { opacity: 1, y: 0, duration: 1, stagger: 0.08, ease: 'power3.out', clearProps: 'transform' }); },
    });
  }

  function motion() {
    if (!gsap || !window.ScrollTrigger || reduced) return;

    // the heads
    $('.hx__meta').forEach(function (m) {
      gsap.fromTo(m, { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: 1, ease: 'power3.out', scrollTrigger: { trigger: m, start: 'top 90%' } });
    });
    $('.hx__title').forEach(function (t) {
      gsap.fromTo(t.querySelectorAll('.hx__wi'), { yPercent: 112 }, { yPercent: 0, duration: 1.35, stagger: 0.06, ease: 'expo.out', scrollTrigger: { trigger: t, start: 'top 86%' } });
    });
    $('.hx__lede').forEach(function (l) {
      gsap.fromTo(l, { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 1, ease: 'power3.out', scrollTrigger: { trigger: l.parentNode, start: 'top 78%' } });
    });

    // our craft: the wall's photographs, the way on, the numbers
    frames('.craft-wall__tile');
    rise('.craft-wall__more');
    rise('.craft__stats .stat__label', 'top 94%');
    $('.stat__value').forEach(function (v) {
      var txt = v.textContent.trim();
      var m = txt.match(/^([\d,]+)(.*)$/);
      if (!m) return;
      var end = parseInt(m[1].replace(/,/g, ''), 10);
      var from = end >= 1000 && end < 2100 && !/,/.test(m[1]) ? end - 60 : 0;   // a year counts up through its last decades
      var comma = /,/.test(m[1]);
      var o = { n: from };
      var paint = function () {
        var n = Math.round(o.n);
        v.textContent = (comma ? n.toLocaleString('en-IN') : String(n)) + m[2];
      };
      paint();
      gsap.to(o, { n: end, duration: 2, ease: 'power3.out', onUpdate: paint, onComplete: function () { v.textContent = txt; }, scrollTrigger: { trigger: v, start: 'top 92%' } });
    });

    // the curated edit: the tabs, the pieces, the promises
    rise('.curated__filter', 'top 94%');
    frames('.curated__grid .piece', '.piece__media');
    rise('.curated__grid .piece:not([hidden]) .piece__info');
    rise('.curated__more');
    rise('.curated__promises .promise', 'top 95%');
    // a new tab's pieces open in turn
    $('.curated__filter').forEach(function (btn) {
      btn.addEventListener('click', function () {
        setTimeout(function () {
          $('.curated__grid .piece').filter(shown).forEach(function (p, i) {
            var media = p.querySelector('.piece__media');
            gsap.killTweensOf(media);
            open(media, i * 0.07);
            gsap.fromTo(p.querySelector('.piece__info'), { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.8, delay: 0.25 + i * 0.07, ease: 'power3.out', clearProps: 'transform' });
          });
          window.ScrollTrigger.refresh();
        }, 0);
      });
    });

    // the reviews: the card opens, then its cells
    var tw = document.querySelector('.tw');
    if (tw) {
      gsap.fromTo(tw, { clipPath: 'inset(100% 0% 0% 0% round 6px)' }, { clipPath: 'inset(0% 0% 0% 0% round 6px)', duration: 1.4, ease: 'expo.out', clearProps: 'clipPath', scrollTrigger: { trigger: tw, start: 'top 85%' } });
      rise('.tw__head > *', 'top 85%');
      rise('.tw__grid > *', 'top 92%');
    }

    // the journal
    frames('.journal-feature__media');
    rise('.journal-feature__body > *');
    frames('.journal-card__media');
    rise('.journal-card__title');

    // the questions
    rise('.faq__item', 'top 94%');

    // the festive edit
    frames('.shopcta__media');
    rise('.shopcta__panel > *');
  }

  if (window.__sjRevealed || !document.querySelector('.sj-loader')) motion();
  else document.addEventListener('sj:revealed', motion, { once: true });
})();

/* The reviews, one at a time, and the journal's grid. */
(function () {
  var gsap = window.gsap;
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
  var $ = function (s, r) { return [].slice.call((r || document).querySelectorAll(s)); };

  // ================= the reviews =================
  var tq = document.querySelector('.tq');
  if (tq) {
    var slides = $('.tq__slide', tq), shots = $('.tq__shot', tq), dots = $('.tq__dot', tq);
    var countNo = tq.querySelector('.tq__count b');
    var n = slides.length, cur = 0, timer = null, inView = false, hovering = false, focused = false, busy = false;
    var HOLD = 7;

    // every quote's words in their own boxes, so they can rise
    slides.forEach(function (s) {
      var q = s.querySelector('.tq__quote');
      q.innerHTML = q.textContent.trim().split(/\s+/).map(function (w) {
        return '<span class="tq__w"><span class="tq__wi">' + w + '</span></span>';
      }).join(' ');
    });

    function show(i, dir) {
      i = (i + n) % n;
      if (i === cur || busy) return;
      var from = cur;
      cur = i;
      dir = dir || (i > from ? 1 : -1);
      var oldS = slides[from], newS = slides[i], oldP = shots[from], newP = shots[i];
      slides.forEach(function (s, k) { s.setAttribute('aria-hidden', k === i ? 'false' : 'true'); });
      shots.forEach(function (s, k) { s.setAttribute('aria-hidden', k === i ? 'false' : 'true'); s.tabIndex = k === i ? 0 : -1; });
      dots.forEach(function (d, k) { d.classList.toggle('is-active', k === i); });
      if (countNo) countNo.textContent = String(i + 1).padStart(2, '0');

      if (!gsap || reduced) {
        oldS.classList.remove('is-active'); newS.classList.add('is-active');
        oldP.classList.remove('is-active'); newP.classList.add('is-active');
        return;
      }
      busy = true;
      // the quote: the old one lifts away, the new one's words rise in
      gsap.to(oldS, { opacity: 0, y: -14 * dir, duration: 0.4, ease: 'power2.in', onComplete: function () {
        oldS.classList.remove('is-active');
        gsap.set(oldS, { clearProps: 'opacity,transform,visibility' });
      } });
      gsap.set(newS, { opacity: 1, y: 0, visibility: 'visible' });
      newS.classList.add('is-active');
      gsap.fromTo(newS.querySelectorAll('.tq__wi'), { yPercent: 110 }, { yPercent: 0, duration: 1.05, stagger: 0.014, ease: 'expo.out', delay: 0.3 });
      gsap.fromTo(newS.querySelector('.tq__who'), { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.8, delay: 0.55, ease: 'power3.out', clearProps: 'transform' });
      // the photograph: the next one wipes up over the last (down, going back)
      oldP.classList.add('is-leaving');
      oldP.classList.remove('is-active');
      newP.classList.add('is-active');
      gsap.fromTo(newP, { clipPath: dir > 0 ? 'inset(100% 0% 0% 0%)' : 'inset(0% 0% 100% 0%)' }, {
        clipPath: 'inset(0% 0% 0% 0%)', duration: 1.15, ease: 'expo.inOut',
        onComplete: function () { oldP.classList.remove('is-leaving'); gsap.set(newP, { clearProps: 'clipPath' }); busy = false; },
      });
      gsap.fromTo(newP.querySelector('img'), { scale: 1.18 }, { scale: 1, duration: 1.6, ease: 'expo.out', clearProps: 'transform,scale' });
      gsap.fromTo(newP.querySelector('.tq__cap'), { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: 0.8, delay: 0.6, ease: 'power3.out', clearProps: 'transform' });
      gsap.to(oldP.querySelector('img'), { scale: 1.06, duration: 1.15, ease: 'expo.inOut', clearProps: 'transform,scale' });
      queue();
    }

    // moving on by itself: only while it is on screen, not under the cursor
    function queue() {
      if (timer) timer.kill();
      timer = null;
      if (!gsap || reduced || !inView || hovering || focused) return;
      timer = gsap.delayedCall(HOLD, function () { show(cur + 1, 1); });
    }

    tq.querySelector('.tq__arrow--next').addEventListener('click', function () { show(cur + 1, 1); });
    tq.querySelector('.tq__arrow--prev').addEventListener('click', function () { show(cur - 1, -1); });
    dots.forEach(function (d, k) { d.addEventListener('click', function () { show(k); }); });
    tq.addEventListener('pointerenter', function () { hovering = true; queue(); });
    tq.addEventListener('pointerleave', function () { hovering = false; queue(); });
    // a keyboard visitor inside it holds it still too; a click does not
    tq.addEventListener('focusin', function (e) { focused = e.target.matches(':focus-visible'); queue(); });
    tq.addEventListener('focusout', function (e) { if (!tq.contains(e.relatedTarget)) { focused = false; queue(); } });
    // a swipe on the photograph, on a phone
    var sx = null;
    tq.querySelector('.tq__photo').addEventListener('touchstart', function (e) { sx = e.touches[0].clientX; }, { passive: true });
    tq.querySelector('.tq__photo').addEventListener('touchend', function (e) {
      if (sx === null) return;
      var dx = e.changedTouches[0].clientX - sx;
      sx = null;
      if (Math.abs(dx) > 40) show(cur + (dx < 0 ? 1 : -1), dx < 0 ? 1 : -1);
    });
    new IntersectionObserver(function (e) { inView = e[0].isIntersecting; queue(); }, { threshold: 0.35 }).observe(tq);
    document.addEventListener('visibilitychange', function () { inView = !document.hidden && inView; queue(); });
  }

  // ================= the journal's "Read" disc =================
  var grid = document.querySelector('.jr__grid');
  var disc = document.querySelector('.jr__cursor');
  if (grid && disc && fine) {
    grid.classList.add('has-cursor');
    var x = 0, y = 0, tx = 0, ty = 0, raf = 0, on = false;
    var follow = function () {
      x += (tx - x) * 0.2;
      y += (ty - y) * 0.2;
      disc.style.transform = 'translate3d(' + (x - 46) + 'px,' + (y - 46) + 'px,0)';
      if (on || Math.abs(tx - x) > 0.5 || Math.abs(ty - y) > 0.5) raf = requestAnimationFrame(follow);
      else raf = 0;
    };
    var run = function () { if (!raf) raf = requestAnimationFrame(follow); };
    $('.jr__tile', grid).forEach(function (t) {
      t.addEventListener('pointerenter', function (e) {
        if (!on) { x = tx = e.clientX; y = ty = e.clientY; }
        on = true;
        disc.classList.add('is-on');
        run();
      });
      t.addEventListener('pointermove', function (e) { tx = e.clientX; ty = e.clientY; run(); });
      t.addEventListener('pointerleave', function () { on = false; disc.classList.remove('is-on'); });
    });
  }

  // ================= the entrances =================
  function motion() {
    if (!gsap || !window.ScrollTrigger || reduced) return;
    if (tq) {
      var first = tq.querySelector('.tq__slide.is-active');
      var tl = gsap.timeline({ scrollTrigger: { trigger: tq, start: 'top 80%' } });
      tl.fromTo(tq.querySelector('.tq__panel'), { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.3, ease: 'expo.out', clearProps: 'clipPath' }, 0)
        .fromTo(tq.querySelector('.tq__photo'), { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.3, ease: 'expo.out', clearProps: 'clipPath' }, 0.1)
        .fromTo(tq.querySelector('.tq__shot.is-active img'), { scale: 1.22 }, { scale: 1, duration: 1.8, ease: 'expo.out', clearProps: 'transform,scale' }, 0.1)
        .fromTo(first.querySelectorAll('.tq__wi'), { yPercent: 110 }, { yPercent: 0, duration: 1.2, stagger: 0.016, ease: 'expo.out' }, 0.45)
        .fromTo([first.querySelector('.tq__who'), tq.querySelector('.tq__top'), tq.querySelector('.tq__shot.is-active .tq__cap')], { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.9, stagger: 0.08, ease: 'power3.out', clearProps: 'transform' }, 0.7)
        .fromTo(tq.querySelectorAll('.tq__dot, .tq__loved, .tq__arrow'), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.7, stagger: 0.03, ease: 'power3.out', clearProps: 'transform' }, 0.85);
    }
    if (grid) {
      $('.jr__tile', grid).forEach(function (t, i) {
        var tl = gsap.timeline({ scrollTrigger: { trigger: t, start: 'top 90%' } });
        tl.fromTo(t, { clipPath: 'inset(100% 0% 0% 0%)' }, { clipPath: 'inset(0% 0% 0% 0%)', duration: 1.25, ease: 'expo.out', delay: (i % 3) * 0.09, clearProps: 'clipPath' })
          .fromTo(t.querySelector('.jr__img'), { scale: 1.22 }, { scale: 1, duration: 1.7, ease: 'expo.out', clearProps: 'transform,scale' }, '<')
          .fromTo(t.querySelectorAll('.jr__tag, .jr__cap'), { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.9, stagger: 0.08, ease: 'power3.out', clearProps: 'transform' }, '<0.4');
      });
      var foot = document.querySelector('.jr__foot');
      if (foot) gsap.fromTo(foot, { opacity: 0, y: 16 }, { opacity: 1, y: 0, duration: 1, ease: 'power3.out', scrollTrigger: { trigger: foot, start: 'top 95%' } });
    }
  }

  if (window.__sjRevealed || !document.querySelector('.sj-loader')) motion();
  else document.addEventListener('sj:revealed', motion, { once: true });
})();

